// CPR/First Aid Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering different situations from Practice Tests 1–5.
import {q, mix} from './q.js';
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-6',
 event:'CPR/First Aid',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:mix([
  q(GEN,'Without CPR or defibrillation, about how much does the chance of surviving cardiac arrest fall each minute?','About 7–10% per minute',['About 1% per hour, so speed matters little','About 50% per minute in every case','It does not change until 30 minutes pass'],'A','Each minute without CPR and defibrillation lowers survival by roughly 7–10%, which is why bystanders should act at once.',AHA_BLS),
  q(GEN,'A teen baseball player is hit in the chest by a ball and collapses, unresponsive and not breathing. What is the likely cause, and what is needed?','Commotio cordis causing VF; start CPR and use an AED fast',['A bruised rib only; have him rest on the bench','Heat cramps; give a sports drink and stretch','A concussion; keep him awake and check pupils'],'B','A blow to the chest at the wrong moment in the heartbeat can trigger ventricular fibrillation (commotio cordis); immediate CPR and an AED save lives.',AHA_BLS),
  q(GEN,'What is the most common initial heart rhythm in adults with sudden witnessed cardiac arrest?','Ventricular fibrillation (VF)',['Normal sinus rhythm with a strong pulse','A slow but steady rhythm with a weak pulse','First-degree heart block with no symptoms'],'C','Most sudden adult cardiac arrests begin in VF, a shockable rhythm, which is why early defibrillation is so effective.',AHA_BLS),
  q(GEN,'After a resuscitation attempt, a team leader holds a short debriefing. What is its main purpose?','To review performance and improve future care',['To decide who is to blame for the outcome','To complete the patient’s billing paperwork','To repeat CPR on a manikin for practice only'],'D','Debriefing lets the team discuss what went well and what to improve, which is linked to better CPR quality in later events.',AHA_BLS),
  q(CPR,'An infant has a heart rate below 60 beats per minute with poor perfusion, even with good breaths. What should the rescuer do?','Begin chest compressions',['Keep giving breaths only and recheck in 10 minutes','Wait for the heart rate to fall to zero first','Give back blows to stimulate the heart'],'A','In infants and children, a heart rate under 60/min with signs of poor perfusion despite ventilation calls for chest compressions.',AHA_BLS),
  q(CPR,'During CPR on an older adult, the rescuer feels a rib crack. What should the rescuer do?','Continue CPR, checking that hand position is correct',['Stop CPR, since broken ribs can puncture a lung','Switch to compressions on the upper abdomen','Reduce depth to 1 inch to protect the ribs'],'B','Rib fractures are common during CPR and are far less dangerous than stopping; confirm hand position and keep compressing at full depth.',ARC_BLS),
  q(CPR,'How should a healthcare provider assess an unresponsive adult before CPR?','Check breathing and pulse at the same time, within 10 seconds',['Check breathing for one minute, then the pulse for one minute','Check the pupils and blood pressure before anything else','Check the pulse only after giving five rescue breaths'],'C','Providers scan for normal breathing while feeling for a carotid pulse at the same time, taking at least 5 but no more than 10 seconds.',AHA_BLS),
  q(CPR,'Why is a compression rate faster than 120 per minute discouraged?','Compressions often become too shallow at very fast rates',['Faster rates always cause the heart to restart too early','The AED cannot analyze when compressions are too fast','Faster rates increase the number of breaths needed'],'D','As rates rise above 120/min, compression depth tends to fall and the heart has less time to refill, lowering blood flow.',AHA_BLS),
  q(CPR,'A lone rescuer with a cell phone finds an adult in cardiac arrest. What is the best way to call for help?','Call 911 on speaker and start CPR while talking',['Run to find a landline before starting CPR','Text a friend and begin CPR after a reply','Do CPR for 10 minutes before calling 911'],'A','With a mobile phone, a lone rescuer can call 911, put it on speaker and begin CPR immediately while the dispatcher helps.',AHA_BLS),
  q(CPR,'Two rescuers arrive at a child in cardiac arrest. What should the second rescuer do while the first starts CPR?','Go call 911 and bring back the AED',['Wait nearby until the first rescuer gets tired','Check the child’s blood pressure with a cuff','Look for the child’s parents before acting'],'B','With two rescuers, one starts CPR right away while the other activates emergency response and gets the AED.',AHA_BLS),
  q(AED,'Who may use an AED on a person in cardiac arrest?','Anyone, including untrained bystanders, by following its prompts',['Only paramedics and emergency room physicians','Only people who have a current BLS certification card on hand','Only a nurse who works in the person’s own clinic'],'A','AEDs are designed for the public: they give voice prompts and shock only if a shockable rhythm is found, so anyone can use one.',AHA_BLS),
  q(AED,'On a small child, AED pads placed on the front of the chest would touch each other. What should be done?','Place one pad on the chest and one on the back',['Stack the pads on top of each other on the chest','Cut the pads in half so both fit on the front','Skip the AED and continue CPR until EMS arrives'],'B','Pads must not touch; if they would overlap on a small chest, use front-and-back (anterior-posterior) placement.',AHA_BLS),
  q(AED,'Which heart rhythms can an AED shock?','Ventricular fibrillation and pulseless ventricular tachycardia',['Asystole (flatline) and normal sinus rhythm with a pulse','Any rhythm at all, as long as the person is unresponsive','Only slow rhythms under 40 beats per minute with a pulse'],'C','AEDs shock only VF and pulseless VT; they do not shock asystole or pulseless electrical activity.',AHA_BLS),
  q(AED,'What is the goal of a public access defibrillation (PAD) program?','To place AEDs and trained people where arrests may occur',['To replace 911 calls with AED use in public places','To train the public to give heart medicines by mouth','To keep AEDs locked away until paramedics arrive'],'D','PAD programs put AEDs in places such as schools, airports and gyms and train responders so shocks can be given within minutes.',AHA_BLS),
  q(ADV,'During CPR with an advanced airway, end-tidal CO2 suddenly rises to about 40 mm Hg. What does this suggest?','Return of spontaneous circulation (ROSC)',['The tube has slipped into the esophagus','Compressions have become too shallow','The patient is breathing too fast'],'A','An abrupt, sustained rise in ETCO2 to 35–40 mm Hg or more is a strong sign that circulation has returned.',AHA_BLS),
  q(ADV,'A provider is placing an endotracheal tube during CPR. How long should compressions be paused, if at all?','As briefly as possible, ideally under 10 seconds',['As long as needed, even several minutes','Compressions must stop until it is fully secured','For exactly 30 seconds to view the vocal cords'],'B','Intubation should minimize interruptions; compressions continue as much as possible, with any pause kept under about 10 seconds.',AHA_BLS),
  q(RB,'Why do pocket masks used for rescue breaths have a one-way valve?','To keep the person’s exhaled air and fluids away from the rescuer',['To deliver oxygen and medicine automatically with each breath','To measure the oxygen level in the person’s blood','To make each breath stronger without extra effort'],'C','A one-way valve lets the rescuer’s breath in while directing the person’s exhaled air and fluids away from the rescuer.',ARC_BLS),
  q(RB,'A person vomits while receiving rescue breaths. What should the rescuer do?','Turn the person on their side, clear the mouth, then continue',['Keep giving breaths so the vomit is pushed down','Stop all care and wait for EMS to clean the airway','Give abdominal thrusts until the vomiting ends'],'D','Roll the person onto their side to let the vomit drain, wipe out the mouth, roll them back and continue care.',ARC_BLS),
  q(CH,'After abdominal thrusts dislodge a piece of food, the person feels fine. What should the rescuer advise?','See a healthcare provider, since thrusts can cause internal injury',['Nothing more is needed once the food is out of the airway','Eat quickly to make up for the missed meal','Lie down flat and sleep for several hours'],'A','Abdominal thrusts can injure internal organs, so anyone who received them should be checked by a healthcare provider.',AHA_FA),
  q(CH,'Which sign is widely recognized as the universal sign of choking?','Clutching the throat with one or both hands',['Pointing repeatedly at the chest and nodding','Waving both arms above the head while coughing','Holding the stomach while bending at the waist'],'B','Clutching the throat is the universal choking sign; ask “Are you choking?” and act if the person cannot speak or cough well.',AHA_FA),
  q(BASIC,'A conscious adult says “Yes, please help me” after you explain who you are. What kind of consent is this?','Expressed consent',['Implied consent','Parental consent','Informed refusal'],'A','Expressed (actual) consent is given verbally or by gesture by a responsive adult after the rescuer explains who they are and what they will do.',ARC_FA),
  q(BASIC,'What is the difference between a dressing and a bandage?','A dressing covers the wound; a bandage holds it in place',['A bandage covers the wound; a dressing is a splint','They are the same item with two different names','A dressing is used only on burns, and a bandage only on cuts'],'B','A sterile dressing is placed directly on a wound; a bandage holds the dressing in place, applies pressure or supports an injury.',DHO),
  q(BASIC,'After giving first aid, a rescuer finds a used needle at the scene. How should it be disposed of?','In a puncture-resistant sharps container, without recapping',['In a regular trash can after bending the needle in half','Recapped by hand, then put in a paper bag','Flushed down a toilet to keep others safe'],'C','Used sharps go into a labeled, puncture-resistant sharps container; never recap, bend or break them by hand.',AHA_FA),
  q(BASIC,'A rescuer has trouble sleeping and keeps thinking about a serious emergency they helped with. What is the best advice?','Talk with someone they trust or a counselor about it',['Ignore the feelings since they will pass on their own','Avoid giving first aid ever again to prevent stress','Keep the event secret from everyone they know'],'D','Strong reactions after an emergency are common; talking with trusted people or a mental health professional helps rescuers cope.',ARC_FA),
  q(BASIC,'A bystander is unsure whether a situation is serious enough to call 911. What should they do?','Call 911 and let the dispatcher decide',['Wait 30 minutes to see if the person gets better on their own','Drive the person to the hospital in their own car first','Post a question online and wait for advice'],'A','Dispatchers are trained to judge the emergency and can give instructions until help arrives.',ARC_FA),
  q(BASIC,'What is a typical normal oral body temperature?','About 98.6 °F (37 °C)',['About 94 °F (34.4 °C)','About 103 °F (39.4 °C)','About 90 °F (32.2 °C)'],'B','Normal oral temperature averages about 98.6 °F (37 °C) and varies slightly through the day; 100.4 °F or more is a fever.',DHO),
  q(BASIC,'Under standard precautions, how should a first aider treat blood from an injured stranger?','As potentially infectious, using gloves and barriers',['As safe if the person says they are healthy','As safe once it has dried on the skin','As infectious only if the person looks ill'],'C','Standard precautions treat all blood and body fluids as potentially infectious, so gloves and barriers are used every time.',AHA_FA),
  q(MED,'A person with diabetes is shaky, sweaty, pale and confused. What is most likely happening?','Low blood sugar (hypoglycemia)',['A mild case of seasonal allergies','High blood pressure from stress alone','A sprained muscle in the upper back'],'D','Shakiness, sweating, paleness, hunger and confusion are classic signs of low blood sugar; give sugar if the person can swallow safely.',AHA_FA),
  q(MED,'During a seizure, what should a first aider never do?','Put anything in the person’s mouth',['Move nearby objects out of the way','Time how long the seizure lasts','Place something soft under the head'],'A','Objects in the mouth can break teeth or block the airway; people cannot swallow their tongue. Protect the head and time the seizure.',AHA_FA),
  q(MED,'After a seizure ends, the person is breathing but drowsy and confused. What is the best care?','Place them on their side and let them rest while watching breathing',['Give them a large glass of water right away to help them recover','Ask them to stand up and walk to check balance','Restrain their arms in case another seizure starts'],'B','After a seizure, people are often confused and tired; the recovery position keeps the airway clear while they recover.',AHA_FA),
  q(MED,'Why should a person with signs of stroke not be given food or drink?','Stroke can impair swallowing, raising the risk of choking',['Food will make the stroke symptoms disappear too fast','Drinks always raise blood pressure to dangerous levels','Eating will interfere with the ambulance ride'],'C','Stroke often weakens the muscles used to swallow, so food or drink could be inhaled; give nothing by mouth and call 911.',AHA_FA),
  q(MED,'A person with low blood sugar ate 15–20 g of sugar but still feels shaky after 15 minutes. What should happen next?','Give more sugar and call 911 if they do not improve',['Give insulin to bring their sugar level back down','Have them go to sleep until the feeling passes','Wait another hour before doing anything else'],'D','If symptoms continue about 15 minutes after giving sugar, give more; call 911 if the person worsens or does not improve.',AHA_FA),
  q(MED,'A person’s face droops and their arm is weak, but it all goes away within 10 minutes. What should happen?','Call 911 anyway, because it may be a warning stroke (TIA)',['Nothing, since the symptoms have already gone away','Have them take a nap and see how they feel later','Give them aspirin and send them back to work'],'A','A transient ischemic attack can come before a major stroke; even when symptoms resolve, call 911 for urgent evaluation.',AHA_FA),
  q(MED,'A person has chest pain. They are not allergic to aspirin and have no bleeding problems. What may a first aider do after calling 911?','Help them chew one adult (325 mg) or 2 to 4 low-dose aspirin tablets',['Give them 6 regular aspirin tablets to swallow whole with water','Give them ibuprofen instead of aspirin','Give them nothing by mouth for any reason, even if they ask for aspirin'],'B','Chewing aspirin can slow clot growth during a heart attack if the person has no reason to avoid it.',ARC_FA),
  q(MED,'A person in anaphylaxis feels faint but is breathing well. How should they be positioned?','Lying flat with the legs raised, if breathing allows',['Standing up and walking to keep blood moving','Sitting on a high stool with feet dangling','Lying face down with the head turned to one side'],'C','A person with low blood pressure from anaphylaxis should lie down with legs raised; sitting up may help if breathing is hard.',AHA_FA),
  q(MED,'Which is a common trigger of anaphylaxis?','Insect stings, peanuts and shellfish',['Drinking plain water at room temperature','Sitting in the sun for a few minutes','Walking on a cool, grassy field'],'D','Common triggers include foods such as peanuts, tree nuts and shellfish, insect stings and some medicines.',AHA_FA),
  q(INJ,'A burn involves the face, hands or genitals. Why does it need medical care even if small?','These areas affect breathing, function or carry a high risk',['Burns there always heal in a day with no care','These burns never become infected or leave any scar behind','Burns there are less painful than other burns'],'A','Burns to the face, hands, feet, genitals or major joints can affect breathing, function and appearance, so they need medical care.',AHA_FA),
  q(INJ,'A first aider has a hemostatic dressing for severe bleeding. How should it be used?','Packed or placed on the wound with firm, direct pressure',['Placed loosely on top of clothing without pressure','Used only after a tourniquet has failed twice','Soaked in water and laid gently next to the wound'],'B','Hemostatic dressings help blood clot, but they work only with firm, direct pressure applied on the bleeding site.',AHA_FA),
  q(INJ,'After a head injury, clear fluid or blood drains from an ear. What should the first aider do?','Let it drain, cover lightly and call 911',['Plug the ear firmly with cotton to stop it','Have the person shake their head to clear it','Rinse the ear with warm water and soap'],'C','Fluid from the ear after head injury may be cerebrospinal fluid from a skull fracture; do not block it. Call 911 and keep the person still.',AHA_FA),
  q(INJ,'A person with a suspected spine injury begins to vomit. How should they be moved?','Roll them onto their side as a unit, keeping head and spine aligned',['Sit them upright quickly so they can lean forward','Lift only their head and turn it sharply to one side to drain','Leave them flat on their back while they vomit'],'D','If the airway must be protected, log-roll the person with helpers, keeping the head, neck and body in line.',ARC_FA),
  q(INJ,'Which cut most likely needs stitches?','A gaping cut more than ½ inch long with edges that do not close',['A shallow paper cut that stopped bleeding in a minute','A small scrape that bled a little and then crusted','A bruise with no break in the skin at all'],'A','Deep or gaping cuts, cuts longer than about ½ inch, or ones on the face or joints often need stitches, ideally within hours.',AHA_FA),
  q(INJ,'A large cut on the side of the neck is bleeding heavily. Why is an occlusive dressing used?','To stop air from being drawn into a large vein',['To keep the neck cool and reduce swelling','To hold a splint against the collarbone','To let the wound dry out more quickly'],'B','Open neck veins can draw in air (air embolism), so an airtight dressing with careful pressure is used without blocking the airway.',ARC_FA),
  q(INJ,'For the first 48 hours after a sprain, which is generally recommended?','Cold packs, wrapped in a cloth, for about 20 minutes at a time',['A heating pad on high for several hours at a time, then ice','Hot baths several times a day to loosen the joint','Massaging the joint hard to break up the swelling'],'C','Cold reduces swelling and pain early on; apply it with a barrier for about 20 minutes, while heat is avoided in the first 48 hours.',DHO),
  q(INJ,'Which finding most suggests a fracture rather than a minor bruise?','Deformity, grating and inability to use the limb',['Mild soreness that eases after a short rest','A small red mark with full movement of the limb','Slight itching around a minor scratch'],'D','Signs of a fracture include deformity, severe pain, swelling, grating (crepitus) and loss of use; splint and seek medical care.',DHO),
  q(INJ,'A flap of skin is partly torn away from the hand. What type of wound is this?','An avulsion',['An abrasion','A contusion','A puncture'],'A','An avulsion partly or fully tears tissue away; lay the flap back in place if possible, cover and press to control bleeding.',DHO),
  q(ENV,'A hiker at high altitude develops headache, nausea and trouble walking straight. What is the most important treatment?','Descend to a lower altitude',['Climb higher to adjust faster','Drink alcohol to warm up','Sleep at the same altitude'],'B','Altitude illness improves with descent; confusion or loss of coordination suggests severe illness that needs immediate descent and care.',ARC_FA),
  q(ENV,'Right after touching poison ivy, what is the best first aid?','Wash the skin with soap and water as soon as possible',['Scratch the area firmly to remove the plant oil','Cover the skin with a tight bandage for a day','Rub the area with a dry towel and do nothing else'],'C','Washing with soap and water soon after contact removes the oil (urushiol) and can prevent or lessen the rash; wash clothing too.',AHA_FA),
  q(ENV,'Why does a person in wet clothing on a windy, cool day lose body heat quickly?','Water and wind draw heat away from the body much faster',['Wet clothing holds heat in better than dry clothing','Wind has no effect on body temperature at all','Cool air only affects people who are not moving'],'D','Water conducts heat away far faster than air, and wind adds to the loss; remove wet clothes and shelter the person.',ARC_FA),
  q(ENV,'A child is found in a hot, parked car, confused and with hot skin. What is the priority after removing them?','Cool the child rapidly and call 911',['Wrap the child in a blanket to keep warm','Give the child a large meal immediately','Wait an hour to see if the child improves'],'C','Cars heat quickly and children overheat fast; confusion with hot skin suggests heat stroke, which needs rapid cooling and 911.',AHA_FA),
  q(ENV,'A camper’s feet have been cold and wet for days and are now numb and swollen. What is the best first aid?','Gently dry and warm the feet and keep them elevated',['Rub the feet hard with snow to restore feeling','Walk on them for hours to improve circulation','Soak them in very hot water above 115 °F'],'D','Immersion (trench) foot comes from prolonged cold and wet; dry, gently warm and elevate the feet and seek medical care.',ARC_FA)
 ],9601)
};
